def t(title,content):return dict(type='text',title=title,content=content)
def w(content):return dict(type='warning',title='Граница безопасности и вывода',content=content)
def r(content):return dict(type='remember',content=content)
def q(question,answers,explanation):
    shift=sum(map(ord,question))%len(answers)
    return dict(type='question',question=question,answers=answers[shift:]+answers[:shift],correctAnswer=(-shift)%len(answers),explanation=explanation)
def c(question,value,unit,explanation,tolerance=.01):
    return dict(type='calculation',question=question,correctValue=value,unit=unit,tolerance=tolerance,
                hint='Проверьте границы мощности, единицы и условия модели.',explanation=explanation)


SAFE='Все упражнения — офлайн-анализ готовых синтетических данных и условные расчёты, без действий на автомобиле. Выключение автомобиля не гарантирует отсутствия опасной энергии. Запрещены самостоятельные вскрытие батареи, демонтаж HV-разъёмов, HV-измерения и проверка изоляции, вмешательство в BMS, внешнее питание HV-компонентов, принудительное включение контакторов и обход HVIL. Здесь нет процедур обесточивания, проверки отсутствия напряжения, разряда или ремонта. Нужны квалифицированный специалист и применимая заводская документация; этот урок не даёт допуска к HV-работам.'
BASE='E0 — собственная BEV-модель: HV-батарея 96s2p, номинально 360 V/100 Ah/36 kWh; одна тяговая машина, inverter, OBC и изолированный HV/LV DC/DC. HV− не соединён с кузовом. LV условно 12 V, не стандарт всех EV. B0: идеальные одинаковые ячейки 3,75 V/50 Ah; 192 ячейки, BMS видит 96 напряжений параллельных групп. Числа/статусы не относятся к конкретному автомобилю и не являются нормами ремонта.'
