def main():
    OUT.mkdir(parents=True,exist_ok=True)
    summaries=[];count=tasks=0
    for order,(title,description,minutes,blocks) in enumerate(LESSONS,1):
        lesson=dict(id=f'hybrid_ev_{order:02}',moduleId='stage_13',order=order,title=title,description=description,
                    estimatedMinutes=minutes,completion=dict(type='quiz',passingScore=80) if order==10 else dict(type='lesson'),blocks=blocks)
        def readable(value):
            if isinstance(value,str): return re.sub(r'(?<=[а-яА-ЯёЁ])(?=\d)|(?<=\d)(?=[а-яА-ЯёЁ])',' ',value)
            if isinstance(value,list): return [readable(v) for v in value]
            if isinstance(value,dict): return {k:readable(v) for k,v in value.items()}
            return value
        lesson=readable(lesson)
        file=f'lesson_{order:02}.json'
        (OUT/file).write_text(json.dumps(lesson,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
        summaries.append({k:lesson[k] for k in ['id','order','title','description','estimatedMinutes']}|dict(file=file))
        count+=len(blocks);tasks+=sum(b['type'] in {'question','calculation'} for b in blocks)
    (OUT/'lessons.json').write_text(json.dumps(summaries,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(f'stage_13: {count} blocks / {tasks} tasks')


if __name__=='__main__':main()
